#!/usr/bin/env python3
"""Compute reference values for CSX-057_Q1."""

from __future__ import annotations

import html
import json
import re
from html.parser import HTMLParser
from pathlib import Path
from typing import Any


TASK_ID = "CSX-057_Q1"
EVENT_ID = "CSX-057"
GALLONS_PER_INCH_SQMI = 17_378_742.857


class TextExtractor(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.skip_depth = 0
        self.parts: list[str] = []

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if tag.lower() in {"script", "style", "noscript"}:
            self.skip_depth += 1

    def handle_endtag(self, tag: str) -> None:
        if tag.lower() in {"script", "style", "noscript"} and self.skip_depth:
            self.skip_depth -= 1

    def handle_data(self, data: str) -> None:
        if not self.skip_depth:
            self.parts.append(data)

    def text(self) -> str:
        return re.sub(r"\s+", " ", html.unescape(" ".join(self.parts))).strip()


def read_json(package_dir: Path, rel_path: str) -> Any:
    return json.loads((package_dir / rel_path).read_text(encoding="utf-8-sig"))


def read_html_text(package_dir: Path, rel_path: str) -> str:
    parser = TextExtractor()
    parser.feed((package_dir / rel_path).read_text(encoding="utf-8", errors="replace"))
    return parser.text()


def regex_float(text: str, pattern: str) -> float:
    match = re.search(pattern, text, flags=re.IGNORECASE)
    if not match:
        raise ValueError(f"Pattern not found: {pattern}")
    return float(match.group(1).replace(",", ""))


def regex_int(text: str, pattern: str) -> int:
    return int(regex_float(text, pattern))


def rounded(value: float) -> float:
    return round(value, 2)


def main() -> None:
    repo_root = Path(__file__).resolve().parents[3]
    package_dir = repo_root / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID
    task_dir = Path(__file__).resolve().parent

    event_rel = "metadata/event.json"
    anchor_rel = (
        "data/event_reports/"
        "event_reports_003_Locked_event_anchor_Hurricane_Harvey_Houston_catastrophic_rainfall_flooding.json"
    )
    report_rel = "data/event_reports/event_reports_001_Locked_package_evidence_report.bin"

    event_meta = read_json(package_dir, event_rel)
    anchor = read_json(package_dir, anchor_rel)
    report_text = read_html_text(package_dir, report_rel)

    input_values = {
        "peak_storm_rainfall_inches": regex_float(
            report_text, r"highest rainfall amount totaled ([0-9.]+) inches"
        ),
        "hobby_aug26_29_inches": regex_float(report_text, r"From August 26-29, ([0-9.]+) inches"),
        "houston_august_total_inches": regex_float(
            report_text, r"August was the wettest month on record for the city \(([0-9.]+) inches\)"
        ),
        "previous_wettest_month_inches": regex_float(
            report_text, r"previous wettest month \(([0-9.]+) inches\)"
        ),
        "people_receiving_at_least_20in_million": regex_float(report_text, r"More than ([0-9.]+) million people"),
        "area_receiving_at_least_20in_sq_mi": regex_int(
            report_text, r"million people in a ([0-9,]+) square mile area"
        ),
    }

    people_count = input_values["people_receiving_at_least_20in_million"] * 1_000_000
    area_sq_mi = input_values["area_receiving_at_least_20in_sq_mi"]
    derived_values = {
        "peak_to_20in_ratio": rounded(input_values["peak_storm_rainfall_inches"] / 20),
        "hobby_4day_mean_in_per_day": rounded(input_values["hobby_aug26_29_inches"] / 4),
        "hobby_total_to_20in_ratio": rounded(input_values["hobby_aug26_29_inches"] / 20),
        "houston_month_record_ratio": rounded(
            input_values["houston_august_total_inches"] / input_values["previous_wettest_month_inches"]
        ),
        "exposed_density_per_sq_mi": rounded(people_count / area_sq_mi),
        "min_20in_area_volume_trillion_gal": rounded(20 * area_sq_mi * GALLONS_PER_INCH_SQMI / 1_000_000_000_000),
    }

    pass_tests = {
        "peak_to_20in_ratio_ge_2": derived_values["peak_to_20in_ratio"] >= 2.0,
        "hobby_total_to_20in_ratio_ge_1_5": derived_values["hobby_total_to_20in_ratio"] >= 1.5,
        "houston_month_record_ratio_ge_2": derived_values["houston_month_record_ratio"] >= 2.0,
        "min_20in_area_volume_trillion_gal_ge_10": derived_values["min_20in_area_volume_trillion_gal"] >= 10.0,
    }
    label = (
        "persistent_extreme_rainfall_accumulation"
        if all(pass_tests.values())
        else "threshold_not_met"
    )
    causal_answer = {
        "label": label,
        "causal_graph": {
            "nodes": [
                {
                    "id": "peak_extreme_rainfall",
                    "role": "trigger",
                    "evidence": "peak_to_20in_ratio=2.41",
                },
                {
                    "id": "multi_day_accumulation",
                    "role": "trigger",
                    "evidence": "hobby_4day_mean=8.90 in/day; hobby_total_to_20in_ratio=1.78",
                },
                {
                    "id": "monthly_record_context",
                    "role": "amplifier",
                    "evidence": "houston_month_record_ratio=2.04",
                },
                {
                    "id": "large_area_water_volume",
                    "role": "amplifier",
                    "evidence": "min_20in_area_volume=10.08 trillion gal",
                },
                {
                    "id": "heavy_rain_footprint_receptors",
                    "role": "receptor",
                    "evidence": "exposed_density=231.03 people/sq mi",
                },
                {
                    "id": "short_isolated_downpour",
                    "role": "rejected_alternative",
                    "evidence": "four-day and monthly ratios also exceed the relevant scales",
                },
            ],
            "edges": [
                {
                    "from": "peak_extreme_rainfall",
                    "to": "multi_day_accumulation",
                    "relationship": "peak rainfall is embedded in a sustained multi-day load",
                },
                {
                    "from": "multi_day_accumulation",
                    "to": "large_area_water_volume",
                    "relationship": "persistent rainfall over a broad footprint creates large water volume",
                },
                {
                    "from": "monthly_record_context",
                    "to": "multi_day_accumulation",
                    "relationship": "monthly record ratio confirms persistence beyond one storm hour",
                },
                {
                    "from": "large_area_water_volume",
                    "to": "heavy_rain_footprint_receptors",
                    "relationship": "large water volume intersects populated heavy-rain area",
                },
                {
                    "from": "multi_day_accumulation",
                    "to": "short_isolated_downpour",
                    "relationship": "multi-day and monthly accumulation contradict a short isolated downpour framing",
                },
            ],
        },
        "key_values": derived_values,
        "causal_discriminators": {
            "persistent_accumulation": True,
            "large_area_water_volume": True,
            "exposure_density_context": True,
            "short_isolated_downpour_rejected": True,
        },
        "interpretation": (
            "Harvey is best represented as persistent extreme rainfall accumulation because the peak, "
            "four-day, monthly-record, large-area water-volume, and exposed-footprint metrics reinforce "
            "the same flood pathway."
        ),
    }

    rubric = {
        "total_points": 20,
        "criteria": [
            {
                "name": "Final JSON label and fields",
                "points": 3,
                "description": "Gives persistent_extreme_rainfall_accumulation and returns the requested causal-graph JSON object.",
                "partial_credit": "Award 1 point for the correct label with malformed JSON, or 2 points for a mostly complete object with one or two missing fields.",
            },
            {
                "name": "Extracted input values",
                "points": 4,
                "description": "Uses 48.20 inches, 35.6 inches, 39.11 inches, 19.21 inches, 6.7 million people, and 29,000 square miles.",
                "partial_credit": "Award 1-3 points in proportion to the number of correct values with units.",
            },
            {
                "name": "Rainfall ratio arithmetic",
                "points": 4,
                "description": "Correctly computes 2.41, 8.90 inches per day, 1.78, and 2.04 with appropriate rounding.",
                "partial_credit": "Award 1 point for each correct rainfall-derived value; subtract for wrong denominators or missing rounding.",
            },
            {
                "name": "Exposure density and water-volume conversion",
                "points": 4,
                "description": "Computes 231.03 people per square mile and 10.08 trillion gallons using the stated conversion constant.",
                "partial_credit": "Award 2 points for one of the two derived exposure values, or 3 points if both are structurally correct but one has a rounding or scale error.",
            },
            {
                "name": "Classification rule",
                "points": 3,
                "description": "Applies all four stated cutoffs and explains that each one passes.",
                "partial_credit": "Award 1-2 points for applying only some cutoffs or giving the right label without showing the pass tests.",
            },
            {
                "name": "Concise interpretation",
                "points": 2,
                "description": "Gives a one-sentence interpretation tied to persistent accumulation across the event, four-day, monthly, and large-area metrics without adding extra loss claims.",
                "partial_credit": "Award 1 point for a relevant but incomplete interpretation.",
            },
        ],
    }

    output = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "target_family": "harvey_rainfall_flood_causal_graph",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": causal_answer,
        "key_values": {
            "event_name": event_meta["event_name"],
            "event_window": {
                "start_date": anchor["temporal_window"]["start_date"],
                "end_date": anchor["temporal_window"]["end_date"],
            },
            "input_values": input_values,
            "formulas": {
                "peak_to_20in_ratio": "peak_storm_rainfall_inches / 20",
                "hobby_4day_mean_in_per_day": "hobby_aug26_29_inches / 4",
                "hobby_total_to_20in_ratio": "hobby_aug26_29_inches / 20",
                "houston_month_record_ratio": "houston_august_total_inches / previous_wettest_month_inches",
                "exposed_density_per_sq_mi": "people_receiving_at_least_20in / area_receiving_at_least_20in_sq_mi",
                "min_20in_area_volume_trillion_gal": "20 * area_sq_mi * 17378742.857 / 1e12",
            },
            "derived_values": derived_values,
            "causal_support_tests": pass_tests,
            "thresholds": {
                "peak_to_20in_ratio": 2.0,
                "hobby_total_to_20in_ratio": 1.5,
                "houston_month_record_ratio": 2.0,
                "min_20in_area_volume_trillion_gal": 10.0,
            },
            "numeric_tolerances": {
                "ratios_and_density": 0.01,
                "volume_trillion_gal": 0.02,
            },
        },
        "rubric": rubric,
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [event_rel, anchor_rel, report_rel],
            "notes": "Values are extracted from the local Harvey technical record and converted with the stated gallons-per-inch-square-mile constant.",
        },
    }

    (task_dir / "computed_gt.json").write_text(
        json.dumps(output, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
